 function discover(){const activities=base.games.map((g,i)=>`<button class="activity-card" data-action="activity" data-g="${g.id}">${image(g.cover)}<span>${['食光相遇礼','花园相遇礼','城市启程礼'][i]}</span></button>`).join('');const games=base.games.map(g=>`<article class="game-card" role="button" tabindex="0" data-action="play" data-g="${g.id}">${image(g.icon)}<div class="game-card-main"><h3>${g.name}</h3><div class="game-actions">${btn('codes','兑换码',{g:g.id},'pill')}${btn('recharge','游戏充值',{g:g.id},'pill')}</div></div></article>`).join('');return shell('友趣游戏传送门',`<div class="hero-pad">${btn('search',icon('search',16)+'<span>搜索游戏或帖子</span>',{},'search-entry')}<h3 class="section-title">热门活动</h3><div class="horizontal">${sim.content==='empty'?'暂无活动':activities}</div></div><div class="games-list"><h3 class="section-title">热门游戏</h3>${sim.content==='empty'?empty('暂无游戏'):games}</div>`,{root:true,striped:true,bottom:tabs('N22')});}
 function circle(){const posts=sim.content==='empty'?[]:S.posts.filter(p=>p.type==='discuss'&&p.status==='approved'&&(!ui.filter||p.gameId===ui.filter));return shell('圈子',`<div class="circle-hero">${btn('search',icon('search',16)+'<span>搜索游戏或帖子</span>',{},'search-entry')}<div class="entry-cards">${btn('nav',image('assets/food-icon.svg')+'找攻略／公告',{page:'N23'},'entry-card')}${btn('nav',image('assets/flower-icon.svg')+'找队友',{page:'N18'},'entry-card')}</div></div>${gameChips()}${posts.length?posts.slice(0,ui.limit).map(p=>postCard(p)).join('')+end(posts):empty('暂无帖子')}`,{root:true,striped:true,bottom:tabs('P01')})+btn('top',icon('arrow'),{},'top-button');}
 function guides(){const list=sim.content==='empty'?[]:S.posts.filter(p=>['news','strategy'].includes(p.type)&&(!ui.filter||p.gameId===ui.filter)&&(ui.type==='all'||p.type===ui.type));return shell('攻略与公告',chips([['all','全部'],['strategy','攻略'],['news','公告']],ui.type,'type')+gameChips()+refresh()+list.slice(0,ui.limit).map(p=>postCard(p)).join('')+(list.length?end(list):empty('暂无内容')),{cls:'soft-bg'});}
 function searchPage(){
 const q=ui.search.trim().toLowerCase(),match=p=>[p.title,p.content,p.game].join(' ').toLowerCase().includes(q);
 const accounts=sim.content==='empty'?[]:base.games.filter(g=>g.name.toLowerCase().includes(q));
 const recommended=sim.recommend==='none'?[]:sim.recommend==='one'?base.games.filter(g=>g.id===2):base.games;
 let list=sim.content==='empty'?[]:S.posts.filter(p=>p.type==='discuss'&&p.status==='approved'&&match(p));
 if(ui.searchTab==='综合')list.sort((a,b)=>b.likeCount-a.likeCount);else list.sort((a,b)=>(b.fullDate||b.date||'').localeCompare(a.fullDate||a.date||''));
 const searchbar=`<form class="search-form" data-form="search"><input name="keyword" data-bind="search" value="${esc(ui.search)}" placeholder="搜索游戏或帖子" aria-label="搜索游戏或帖子" enterkeyhint="search"><button type="submit">搜索</button>${btn('clear-search','×')}</form>`;
 let body='';if(!ui.searched)body=`<div class="page-pad"><div class="row-between"><h3 class="section-title">搜索历史</h3>${btn('clear-history',image('static/search/trash.png'),{},'history-clear')}</div><div class="chips search-history">${S.history.map(t=>btn('quick-search',esc(t),{value:t},'chip')).join('')||'<span class="tiny">暂无搜索历史</span>'}</div><h3 class="section-title" style="margin-top:27px">热门搜索</h3><div class="chips search-history">${[...base.games.map(g=>g.name),'日常任务','经营心得'].map(t=>btn('quick-search',esc(t),{value:t},'chip')).join('')}</div></div>`;
 else if(ui.searchTab==='游戏')body=accounts.length?accounts.map(accountCard).join(''):`<div class="recommend-note"><b>没有找到相关游戏，为你推荐其他游戏</b><p>发现更多喜欢的游戏</p></div>${recommended.length?'<div class="page-pad section-gap"><h3 class="section-title">推荐游戏</h3></div>'+recommended.map(accountCard).join(''):empty('暂无推荐游戏')}`;
 else if(ui.searchTab==='关注'){const followed=sim.content==='empty'?[]:base.games.filter(g=>S.follows.includes(g.id));body=!isLogged()?empty('登录后查看关注的游戏主')+btn('login','微信登录',{},'primary search-login'):followed.length?followed.map(accountCard).join(''):empty('暂无关注的游戏主');}
 else body=(ui.searchTab==='综合'&&accounts.length?'<div class="page-pad section-gap"><h3 class="section-title">游戏主</h3></div>'+accounts.map(accountCard).join(''):'')+(ui.searchTab==='综合'&&list.length?'<div class="page-pad section-gap"><h3 class="section-title">热门帖子</h3></div>':'')+(list.length?list.slice(0,ui.limit).map(p=>postCard(p)).join('')+end(list):empty('暂无相关帖子'));
 return nav('搜索')+searchbar+(ui.searched?`<div class="search-tabs">${['综合','实时','游戏','关注'].map(t=>btn('search-tab',t,{value:t},ui.searchTab===t?'active':'')).join('')}</div>`:'')+`<div class="scroll">${body}</div><div class="safe-bottom"></div>`;
 }
 function accountPage(){const g=game(route.params.g),type=ui.accountTab||'discuss';const list=sim.content==='empty'?[]:S.posts.filter(p=>p.gameId===g.id&&(p.official||p.author===g.name)&&p.type===type&&(type!=='discuss'||p.status==='approved')).sort((a,b)=>(b.fullDate||b.date||'').localeCompare(a.fullDate||a.date||''));return shell('游戏主主页',accountCard(g)+`<div class="search-tabs account-tabs">${[['discuss','帖子'],['strategy','攻略'],['news','公告']].map(([value,label])=>btn('account-tab',label,{value},type===value?'active':'')).join('')}</div>`+list.slice(0,ui.limit).map(p=>postCard(p)).join('')+(list.length?end(list):empty('暂无'+({discuss:'帖子',strategy:'攻略',news:'公告'}[type]))),{cls:'soft-bg'});}
 function commentsFor(p){if(!S.comments[p.id])S.comments[p.id]=makeComments(p.id);return S.comments[p.id];}
 function commentCard(c,pid,parent=''){const own=isLogged()&&c.authorId===S.user.id;return `<div class="comment-item">${own?avatar(S.user.avatar,true):image(c.avatar,'avatar')}<div class="comment-main"><div class="comment-name">${esc(own?S.user.name:c.author)}${c.isAuthor?'<span class="author-badge">作者</span>':''}</div><p class="comment-text">${esc(c.content)}</p><div class="comment-meta"><time>${esc(c.date)}</time>${btn('reply','回复',{pid,id:c.id,parent})}${own?btn('delete-comment','删除',{pid,id:c.id,parent}):''}${btn('like-comment',`${image(c.liked?'static/post/zan_active.png':'static/post/zan.png')}<span>${c.likeCount}</span>`,{pid,id:c.id,parent},'comment-like')}</div>${c.replies?.length?`<div class="comment-replies">${c.replies.map(r=>commentCard(r,pid,c.id)).join('')}</div>`:''}</div></div>`;}
 function detailPage(){
 const p=post(route.params.id||'3001');if(!p||sim.content==='empty')return shell('内容详情',`<div class="detail-missing">${empty('帖子不存在或已被删除')}${btn('back','看看别的吧',{},'primary')}</div>`);
 if(p.mine&&!isLogged()&&p.status!=='approved')return shell('内容详情',empty('内容暂不可查看'));
 const audit=p.type==='discuss'&&['pending','rejected'].includes(p.status),interactive=!audit&&p.type!=='recommendation',mine=p.mine&&isLogged();
 let body='';
 if(p.type==='discuss'){
  const state=audit?`<span class="audit ${p.status}">${p.status==='pending'?'审核中':'审核不通过'}</span>`:mine?`<div class="post-ops">${btn('edit-post',image('static/post/edit.png')+'编辑',{id:p.id})}<i></i>${btn('delete-post',image('static/post/del.png')+'删除',{id:p.id})}</div>`:'';
  body=`<article class="discuss-detail"><div class="detail-author">${mine?avatar(S.user.avatar,true):image(p.avatar,'avatar')}<div class="author-info"><strong>${esc(p.mine?S.user.name:p.author)}</strong><time>${esc(p.fullDate)}</time>${p.mine?`<span class="title-badge" style="${frame(level())}">${LEVELS[level()].name}</span>`:''}</div>${state}</div>${p.status==='rejected'&&p.rejectReason?`<div class="reject-reason">原因：${esc(p.rejectReason)}</div>`:''}<p class="detail-text">${esc(p.content).replace(/(#[^\s#]+)/g,'<span class="topic-highlight">$1</span>')}</p>${p.images.length?`<div class="detail-images">${p.images.map((src,i)=>btn('preview-post',image(src),{id:p.id,index:i})).join('')}</div>`:''}</article>`;
 }else body=`<article class="article-detail"><h2 title="${esc(p.title)}">${esc(p.title)}</h2><div class="detail-meta">${image(p.avatar)}<span>${esc(p.author)}</span><time>${esc(p.fullDate)}</time></div>${btn('preview-single',image(p.cover,'detail-cover'),{src:p.cover},'cover-button')}<div class="article-content">${p.content.split('\n').map((t,i)=>[2,4,6].includes(i)&&t.length<18?`<h3>${esc(t)}</h3>`:`<p>${esc(t)}</p>`).join('')}</div></article>`;
 let bottom='<div class="safe-bottom"></div>';
 if(interactive){const comments=commentsFor(p);body+=`<section class="comments-section" id="comment-anchor"><h3>评论　${p.commentCount}</h3>${comments.slice(0,ui.limit).map(c=>commentCard(c,p.id)).join('')}${comments.length?end(comments):'<div class="list-end">暂无评论</div>'}</section>`;bottom=`<footer class="detail-bottom">${image(isLogged()?S.user.avatar:'static/mine/ava.png','avatar')}<form class="legacy-comment-form" data-form="comment"><input class="comment-input" name="comment" data-bind="comment" value="${esc(ui.comment)}" placeholder="说点什么吧..." aria-label="评论内容，按回车发送" enterkeyhint="send"></form><span class="count-action">${image('static/post/comment_black.png')}${p.commentCount}</span>${btn('like-post',`${image(p.liked?'static/post/zan_active.png':'static/post/zan_black.png')}<span>${p.likeCount}</span>`,{id:p.id},'count-action')}</footer>`;}
 else if(audit&&mine)bottom=`<footer class="detail-bottom audit-bottom">${btn('delete-post',image('static/post/del_red.png')+'删除',{id:p.id},'delete-audit')}${p.status==='rejected'?btn('edit-post',image('static/post/edit_black.png')+'重新编辑',{id:p.id},'reedit-audit'):''}</footer>`;
 return shell({discuss:'讨论详情',news:'公告详情',strategy:'攻略详情',recommendation:'推荐详情'}[p.type],body,{bottom});
 }
 function playerPage(){const person=M.playerProfile(route.params.userId||S.user.id);if(!person||sim.content==='empty')return shell('玩家个人主页',empty('该玩家主页暂不可查看'));const l=person.level;return shell(person.own?'个人主页':'玩家主页',`<div class="page-pad"><section class="player-profile-card" style="--profile-color:${LEVELS[l].color}"><div class="profile-medal-background" aria-hidden="true">${medal(l)}</div>${personAvatar(person)}${person.own?btn('edit-profile','编辑资料 &gt;',{},'profile-edit-link'):''}<h2>${esc(person.name)}</h2><div class="title-badge" style="${frame(l)}">${LEVELS[l].name}</div><p class="tiny">Lv.${l} · ${LEVELS[l].name}</p></section>${person.id!==S.user.id?btn('start-chat',icon('chat',19)+' 聊一聊',{peer:person.id},'primary full profile-chat'):''}${person.own?`<section class="info-card linked-accounts"><h3>关联账号</h3>${person.accounts.map(a=>`<div class="linked-account"><span>${game(a.gameId).name}</span><b>游戏ID：${esc(a.account)}</b></div>`).join('')}<div class="linked-account"><span>微信登录Open ID</span><b>${esc(person.openId)}</b></div></section>`:''}<section class="info-card profile-medals"><div class="row-between"><h3>我的勋章</h3><span class="tiny">已解锁 ${l} 枚</span></div><div class="medal-grid">${Array.from({length:l},(_,i)=>btn('medal-preview',`${medal(i+1)}<b>${LEVELS[i+1].name}</b><span class="tiny">Lv.${i+1}</span>`,{level:i+1},'medal-item')).join('')}</div></section></div>`,{cls:'soft-bg'});}
