 function editorTiles(){const d=ui.postDraft;return d.images.map((src,i)=>`<div class="image-card">${btn('preview-single',image(src),{src})}${btn('remove-post-image',image('static/publish/del.png'),{index:i},'remove-image')}</div>`).join('')+(d.images.length<9?btn('upload-post',image('static/publish/add.png')+'<span>图片</span>',{},'upload-card'):'');}
