 return shell('消息',`<div class="message-shortcuts">${shortcut('nav','联系客服','chat',{page:'N17'})}${shortcut('notice','评论与回复','comment',{type:'comment'},isLogged()&&!S.read.includes('comment')?3:0)}${shortcut('notice','收到的赞','like',{type:'like'},isLogged()&&!S.read.includes('like')?12:0)}</div><div class="refresh-row message-read-tools">${btn('all-read','全部已读')}</div><div class="message-feed">${cards||empty('暂无消息')}</div>`,{root:true,bottom:tabs('P02')});
