 function chatPage(){const peer=M.playerProfile(route.params.peerId);if(!isLogged()||!peer||peer.id===S.user.id)return shell('聊天',empty('该会话暂不可查看'));const thread=M.threadFor(peer.id),messages=sim.content==='empty'?[]:[...(thread?.messages||[])].sort((a,b)=>(a.sentAt||a.created).localeCompare(b.sentAt||b.created)||(a.activityOrder||a.order)-(b.activityOrder||b.order)),pending=messages.some(m=>m.from===S.user.id&&m.status==='sending'),draft=ui.chatDrafts[peer.id]||'';const bubbles=messages.slice(-ui.chatLimit).map(m=>{const own=m.from===S.user.id;return `<div class="chat-time">${m.sentAt||m.created}</div><div class="chat-message ${own?'own':''}">${personAvatar(own?M.playerProfile(S.user.id):peer)}<div class="chat-message-main">${m.type==='image'?btn('preview-single',image(m.content,'chat-photo','聊天图片'),{src:m.content},'chat-image-bubble'):`<p class="chat-bubble">${esc(m.content)}</p>`}${m.status==='sending'?'<span class="chat-status">发送中…</span>':m.status==='failed'?btn('chat-retry','发送失败，点击重试',{id:m.id},'chat-status failed'):''}</div></div>`;}).join('');return shell(peer.name,`${messages.length>ui.chatLimit?btn('chat-older','查看更早消息',{},'load-more'):''}${bubbles||'<div class="chat-empty"><span>和'+esc(peer.name)+'打个招呼吧</span></div>'}`,{cls:'chat-scroll',bottom:`<footer class="chat-composer"><textarea data-bind="chat-text" placeholder="发送消息…" aria-label="聊天消息" rows="1" enterkeyhint="send">${esc(draft)}</textarea>${btn('chat-images',icon('post',22),{},'chat-image-picker',pending)}${btn('chat-send','发送',{},'primary chat-send',!draft.trim()||pending)}</footer>`});}
 function scrollChatBottom(){setTimeout(()=>{if(route.id==='N27'){const el=$('.chat-scroll');if(el)el.scrollTop=el.scrollHeight;}},0);}
 function startChat(peerId){requireLogin(()=>{try{M.validPeer(peerId);go('P02',{}, {root:true});go('N27',{peerId});}catch(e){toast(e.message);}});}
 function sendChat(type='text',content,existingId){const peerId=route.params.peerId;if(route.id!=='N27')return;try{M.validPeer(peerId);const text=content??ui.chatDrafts[peerId]??'',thread=M.threadFor(peerId);if(thread?.messages.some(m=>m.from===S.user.id&&m.status==='sending'))return;const failed=thread?.messages.findLast(m=>m.from===S.user.id&&m.type===type&&m.content===text.trim()&&m.status==='failed');const message=existingId?M.retryMessage(peerId,existingId):failed?M.retryMessage(peerId,failed.id):M.queueMessage(peerId,type,text);const model=M,outcome=sim.submit;save();render();scrollChatBottom();setTimeout(()=>{if(M!==model)return;if(!isLogged()){message.status='failed';save();return;}M.finishMessage(peerId,message.id,outcome==='success');if(outcome==='success'&&message.type==='text'&&ui.chatDrafts[peerId]?.trim()===message.content)ui.chatDrafts[peerId]='';save();if(['P02','N27'].includes(route.id)){render();if(route.id==='N27'&&route.params.peerId===peerId)scrollChatBottom();}if(outcome!=='success'&&route.id==='N27')toast('发送失败，请重试');},450);}catch(e){toast(e.message);}}
 function confirmChatImage(src){if(sim.upload==='fail'){toast('图片读取失败，请重试');return;}openLayer({title:'发送图片',sheet:true,html:image(src,'chat-send-preview'),buttons:[['取消',()=>{}],['发送图片',()=>sendChat('image',src)]]});}
 function notices(){const type=route.params.type||'comment',list=!isLogged()||sim.content==='empty'?[]:base.notifications;return shell(type==='like'?'点赞':'评论',`<div class="notice-list">${list.slice(0,ui.limit).map(n=>`<article class="notice-card">${image(n.avatar,'avatar')}<div class="notice-main"><div class="notice-name">${esc(n.author)}</div><div class="notice-meta"><time>${n.date}</time><span>${type==='like'?'点赞了你的帖子':esc(n.summary)}</span></div>${btn('open-post',esc(type==='like'?'点赞了你的帖子':n.summary),{id:n.postId},'notice-original')}${type==='comment'?`<div class="notice-actions">${btn('like-notice',image('static/message/dian_black.png')+'赞',{id:n.id},n.liked?'selected':'')}${btn('reply-notice',image('static/message/comment_black.png')+'回复',{id:n.id})}</div>`:''}</div>${n.cover?btn('open-post',image(n.cover,'notice-cover'),{id:n.postId}):''}</article>`).join('')}</div>${list.length?end(list):'<div class="list-end">暂无数据</div>'}`,{bottom:'<div class="safe-bottom"></div>'});}
 function updates(){const g=game(route.params.g),list=sim.content==='empty'?[]:S.posts.filter(p=>p.gameId===g.id&&['strategy','news'].includes(p.type));return shell(g.name,list.slice(0,ui.limit).map(p=>postCard(p)).join('')+(list.length?end(list):empty('暂无数据')),{cls:'soft-bg'});}
 function codes(){const g=game(route.params.g),list=sim.content==='empty'?[]:S.codes.filter(c=>c.gameId===g.id&&(!ui.searched||c.title.includes(ui.search))&&(ui.channel==='全部渠道'||c.channel===ui.channel));return shell(g.name+' · 兑换码',image(g.cover,'full-cover')+`<form class="search-form" data-form="code-search"><input data-bind="search" value="${esc(ui.search)}" placeholder="搜索活动"><button type="submit">搜索</button>${btn('clear-search','×')}</form>${btn('channels',esc(ui.channel)+' ▾',{},'chip')}`+list.slice(0,ui.limit).map(c=>btn('code-detail',`<h3>${esc(c.title)}</h3><p class="summary">${esc(c.reward)}</p><div class="row-between"><span class="tag">${esc(c.channel)}</span><span class="tiny">${c.permanent?'长期有效':'有效期至 '+c.endAt}</span></div>`,{id:c.id},'info-card order-card')).join('')+(list.length?end(list):empty('暂无兑换码')),{cls:'soft-bg'});}
 function codeDetail(){const member=route.params.source==='member',c=member?S.monthClaims.find(c=>c.id===route.params.id&&c.userId===S.user.id&&isLogged()):S.codes.find(c=>c.id===route.params.id);if(!c)return shell('兑换码详情',empty('兑换码不存在或无查看权限'));const details=member?M.giftDetails(c.gameId,c.level):null,title=member?`Lv.${c.level} ${LEVELS[c.level].name} · ${c.title||details.title}`:c.title,reward=c.reward||details?.reward,expired=member&&isCodeExpired(c),older=validOldCodes(c.id);return shell(game(c.gameId).name,`<article class="redeem-card"><h2>${esc(title)}</h2>${btn(member?'copy-member-code':'copy-code',esc(c.code),{id:c.id},'code-copy'+(expired?' unavailable':''),expired)}<p class="redeem-reward">${esc(reward)}</p><div class="dashed-line"></div><p class="redeem-expire">${c.permanent?'此兑换码长期有效':'兑换有效期至 '+(member?c.expiry:c.endAt)}</p></article>${older.length?btn('old-member-codes','查看仍有效的往期兑换码 ›',{},'outline valid-old-codes'):''}<article class="redeem-card redeem-how"><h3>如何兑换?</h3>${image('static/recharge/jiaocheng.png','tutorial','游戏兑换教程')}</article>`,{cls:'code-detail-page'});}
 function activity(){const g=game(route.params.g),title=['食光相遇礼','花园相遇礼','城市启程礼'][g.id-1];return shell('活动详情',`${image(g.cover,'full-cover')}<div class="page-pad"><span class="tag">${sim.activity==='ended'?'活动已结束':sim.activity==='paused'?'活动暂停':'游戏活动'}</span><h2 style="font-size:23px;margin:7px 0 16px">${title}</h2><div class="info-card soft-bg"><h3>活动奖励</h3><p class="summary">金币 × 1000、游戏道具 × 3</p><div class="kv"><span>活动游戏</span><b>${g.name}</b></div><div class="kv"><span>活动时间</span><b>2026.11.01 — 2026.11.30</b></div></div><h3>如何领取</h3><div class="member-rules">1. 点击“去玩游戏领礼包”，进入对应游戏。<br>2. 在游戏内按活动要求完成任务。<br>3. 达标后在游戏内领取和使用奖励。</div><div class="notice">本期任务：完成一次游戏体验。<br>具体任务及奖励以游戏内展示为准。</div></div>`,{bottom:`<div class="bottom-bar">${btn('activity-claim',sim.activity==='ended'?'活动已结束':sim.activity==='paused'?'活动暂停':sim.activity==='missing'?'暂时无法领取':'去玩游戏领礼包',{g:g.id,title},'primary full',sim.activity!=='live')}</div>`});}

 const orderStatus=o=>({unpaid:'待支付',failed:'支付失败',pending:'已支付 · 到账中',arrived:'已到账',error:'已支付 · 到账异常',closed:'已关闭',refunded:'已退款',refunding:'退款处理中'}[o.status]||'待支付');
 const paymentStatus=o=>({refunded:{title:'已退款',description:'退款已完成，会员累计已同步调整'},refunding:{title:'退款处理中',description:'退款处理中，请以实际退款结果为准'},closed:{title:'订单已关闭',description:'此订单已关闭，不能继续支付'},failed:{title:'支付失败',description:'支付未完成，可在订单中继续支付'}}[o.status]||{title:o.credited?'支付成功':'订单待支付',description:o.credited?(o.status==='arrived'?'已到账至对应游戏账号':o.status==='error'?'游戏到账异常，可在订单中查看进展':'游戏到账处理中'):'请完成微信支付'});
 const accountFor=g=>sim.identity==='ready'?(S.user.accounts.find(a=>a.gameId===Number(g))?.account||''):'';
 function recharge(){const g=game(route.params.g),l=level(),account=accountFor(g.id);return shell('游戏充值',`<div class="page-pad recharge-content"><section class="recharge-game"><div class="row">${image(g.icon,'recharge-logo')}<div><h2>${g.name}</h2><span class="tiny">充值至本人游戏账号</span></div></div></section><section class="recharge-identity"><div class="row">${avatar(S.user.avatar,true)}<div class="identity-copy"><h3>${esc(S.user.name)}</h3><p>Lv.${l} ${LEVELS[l].name}</p></div><div class="discount-stamp"><small>享受充值折扣</small><strong>${l===1?'原价':discount(LEVELS[l].rate)+'折'}</strong></div></div></section><section class="info-card"><h3>即将充值的游戏ID</h3><strong class="game-account">${account?esc(account):sim.identity==='missing'?'尚未获取游戏账号':'账号读取失败'}</strong>${!account?btn('account-retry',sim.identity==='missing'?'去游戏登录':'重新获取',{g:g.id},'outline'):''}</section>${sim.terminal==='restricted'?'<div class="notice">当前环境暂不支持此商品支付。</div>':''}<section><h3>选择充值面额</h3><div class="amount-grid">${[6,30,68,100,128,328,648,1000,3000].map(n=>btn('denom',`<b>¥${n}</b><small>实付 ¥${amount(n*LEVELS[l].rate)}</small>`,{value:n},ui.denom===n?'active':'')).join('')}</div></section><section class="purchase-note"><h3>购买说明</h3><p class="member-rules">本商品为${g.name}指定游戏券，仅限本游戏使用。优惠由平台补贴，走官方虚拟支付（微信支付）。<br>到账内容及使用规则以本游戏商品配置为准。本单按付款前等级计价，升级后的折扣从下一单生效。</p></section></div>`,{close:true,cls:'soft-bg',bottom:`<div class="bottom-bar recharge-footer"><div class="spacer"><span class="tiny">应付金额</span><div class="amount-big"><small>¥</small>${amount(ui.denom*LEVELS[l].rate)}</div></div>${btn('create-order','立即充值',{},'primary',!ui.denom||!account||sim.terminal==='restricted')}</div>`});}
 function paymentResult(){const o=order();if(!o)return shell('支付结果',empty('订单不存在'),{close:true});const paid=o.credited,info=paymentStatus(o);return shell('支付结果',`<div class="result-head"><div class="success-circle ${!paid||o.status!=='arrived'?'pending':''}">${paid?'✓':'…'}</div><h2>${info.title}</h2><p>${info.description}</p></div><div class="result-actions">${btn('order-detail','查看订单',{id:o.id},'primary')}${btn('return-home','返回首页',{},'secondary')}</div><section class="info-card result-order"><h3>订单基础信息</h3><div class="kv game-link-row"><span>游戏</span><div><b>${game(o.gameId).name}</b>${btn('order-game','去游戏查看 &gt;',{g:o.gameId},'text-link')}</div></div><div class="kv"><span>游戏ID</span><b>${esc(o.account)}</b></div><div class="kv"><span>充值面额</span><b>¥${o.face}</b></div><div class="kv"><span>${paid?'实付':'应付'}</span><b>¥${amount(o.paid)}</b></div><div class="kv"><span>订单号</span><div class="order-id-value"><b>${esc(o.id)}</b>${btn('copy-order-id','复制',{},'text-link')}</div></div><div class="kv"><span>订单状态</span><b>${orderStatus(o)}</b></div></section>`,{close:true,cls:'soft-bg'});}
 function orders(){const list=sim.content==='empty'?[]:[...M.ownedOrders()].sort((a,b)=>b.created.localeCompare(a.created));return shell('我的订单',refresh()+(list.length?list.slice(0,ui.limit).map(o=>btn('order-detail',`<div class="row-between"><div class="row">${image(game(o.gameId).icon,'game-icon')}<h3>${game(o.gameId).name}</h3></div><span class="tiny">${orderStatus(o)}</span></div><div class="kv"><span>游戏ID</span><b>${esc(o.account)}</b></div><div class="kv"><span>充值面额 ¥${o.face}</span><b>本单Lv.${o.level} · ${o.rate===1?'原价':discount(o.rate)+'折'}</b></div><div class="amount">${o.credited?'实付':'应付'} ¥${amount(o.paid)}</div>`,{id:o.id},'info-card order-card')).join('')+end(list):empty('暂无订单')),{cls:'soft-bg'});}
 function orderDetail(){const o=order();if(!o)return shell('订单详情',empty('订单不存在'));return shell('订单详情',`<div class="page-pad order-detail-content"><section class="info-card order-product"><div class="row-between"><span class="eyebrow">充值商品信息</span><span class="tag">${orderStatus(o)}</span></div><h2>¥${o.face} 游戏专用券</h2><div class="product-price"><strong>¥${amount(o.paid)}</strong><del>原价 ¥${o.face}</del></div><p class="tiny">${o.credited?'实付金额':'应付金额'} · 本单Lv.${o.level} · ${o.rate===1?'原价':discount(o.rate)+'折'}</p><div class="order-game-block"><div class="row">${image(game(o.gameId).icon,'recharge-logo')}<div><h3>${game(o.gameId).name}</h3><p class="tiny">游戏ID：${esc(o.account)}</p></div></div>${['unpaid','failed'].includes(o.status)?'':btn('order-game','去游戏查看',{g:o.gameId},'secondary full')}</div>${['unpaid','failed'].includes(o.status)?btn('continue-order','继续支付',{id:o.id},'primary full'):''}<p class="summary">${['unpaid','failed'].includes(o.status)?'请先完成支付，支付成功后可查看到账结果。':o.status==='pending'?'支付已完成，正在等待游戏到账。':o.status==='error'?'支付已完成，游戏到账暂时异常。':o.status==='refunded'?'退款已完成，会员累计已同步调整。':o.status==='refunding'?'退款处理中，请以实际结果为准。':'商品仅限对应游戏使用，实际到账以游戏核实结果为准。'}</p></section><section class="info-card order-facts"><h3>订单详情</h3><div class="kv"><span>订单号</span><div class="order-id-value"><b>${esc(o.id)}</b>${btn('copy-order-id','复制',{},'text-link')}</div></div><div class="kv"><span>创建时间</span><b>${o.created}</b></div><div class="kv"><span>支付时间</span><b>${o.paidAt||'尚未支付'}</b></div><div class="kv"><span>支付方式</span><b>官方虚拟支付（微信支付）</b></div><div class="kv"><span>支付及到账状态</span><b>${orderStatus(o)}</b></div>${o.refundedAt?`<div class="kv"><span>退款时间</span><b>${o.refundedAt}</b></div>`:''}${btn('copy-order','复制订单信息',{},'outline full')}</section><p class="member-rules">如需帮助，请前往「消息—联系客服」。</p></div>`,{cls:'soft-bg'});}
 function member(){const l=level(),v=ui.memberPreview,L=LEVELS[l],V=LEVELS[v],next=l<5?LEVELS[l+1]:null,progress=next?Math.min(100,(M.cumulative()-L.min)/(next.min-L.min)*100):100;const perk=(symbol,title,sub)=>`<div class="perk"><span class="symbol">${icon(symbol,27)}</span><b>${title}</b><small>${sub}</small></div>`;return shell('会员详情与权益',`<div class="page-pad"><div class="member-hero"><div class="row">${avatar(S.user.avatar,true)}<div><span class="tiny">${esc(S.user.name)}的会员身份</span><h2>Lv.${l} ${L.name}</h2></div></div><div class="row-between"><span class="meta">累计充值面额 ¥${amount(M.cumulative())}</span><b>${l===1?'原价':discount(L.rate)+'折'}</b></div>${l<5?`<div class="progress"><i style="width:${progress}%"></i></div><span class="tiny">再充值 ¥${amount(next.min-M.cumulative())} 面额可升至Lv.${l+1}</span>`:'<div class="notice">已达最高等级</div>'}</div><div class="row-between"><h3>会员权益</h3>${btn('nav','充值记录 ›',{page:'N11'},'tiny')}</div><div class="level-tabs" style="margin-top:15px">${[1,2,3,4,5].map(n=>btn('member-preview','Lv.'+n,{value:n},v===n?'active':'')).join('')}</div><div class="level-perk-heading"><h3>Lv.${v} ${V.name}</h3><p>累计充值面额满 ¥${V.min}<br>${v===1?'原价充值':'享受'+discount(V.rate)+'折'}</p></div><div class="perks-grid">${perk('order','充值折扣',v===1?'按原价充值':'本等级享受'+discount(V.rate)+'折，本单按付款前等级计价')}${perk('spark','称号与头像框',V.name+'称号，'+['','基础灰色','绿色','蓝色','紫色动态','金色动态'][v]+'头像框，随当前等级自动展示')}${perk('medal','等级勋章',V.name+'勋章，自动展示当前等级；已解锁勋章直接展示在个人主页')}${v>=2?perk('gift','会员月礼包',['','','每月小礼包，游戏币与基础道具','每月中礼包，游戏币与进阶道具','每月大礼包，含限定皮肤或装扮','每月豪华限定礼包，不单独售卖'][v]+'；每款游戏每月各一次，在我的礼包查看兑换码'):''}${v>=3?perk('game','新游与内测','新游优先体验及内测权益；不限名额，满足资格和开放时间即可参与'):''}</div><div class="member-rules">等级仅按传送门内合格充值面额累计，游戏内直接充值不计入。退款后扣减对应面额并重新计算等级。<br>本单使用付款前等级折扣，新等级折扣从下一单生效。预览等级不会改变真实资格。</div></div>`,{cls:'soft-bg'});}
 function rechargeRecords(){const rows=M.ownedOrders().filter(o=>o.credited).flatMap(o=>[{id:o.id,face:o.face,date:o.paidAt||o.created,gameId:o.gameId},...(o.status==='refunded'?[{id:o.id,face:-o.face,date:o.refundedAt||M.now(),gameId:o.gameId}]:[])]).sort((a,b)=>b.date.localeCompare(a.date));const list=sim.content==='empty'?[]:rows;return shell('充值记录',`<div class="page-pad"><div class="member-hero"><span class="meta">累计充值面额</span><h2>¥${amount(M.cumulative())}</h2><span class="tiny">仅统计传送门内合格充值</span></div></div>${list.length?list.slice(0,ui.limit).map(r=>`<div class="list-row"><span class="row-icon">${icon('order')}</span><div class="row-copy"><b>${game(r.gameId).name}</b><p>${r.date}</p><p>${r.id}</p></div><b style="color:${r.face<0?'#bf8e79':'#8d9d85'}">${r.face<0?'−':'＋'}¥${Math.abs(r.face)}</b></div>`).join('')+end(list):empty('暂无充值记录')}`);}

 function validOldCodes(exclude=''){return isLogged()?S.monthClaims.filter(c=>c.userId===S.user.id&&c.month<S.period&&c.id!==exclude&&!isCodeExpired(c)).sort((a,b)=>b.month.localeCompare(a.month)||a.gameId-b.gameId):[];}
 function isCodeExpired(c){return c.expiry<M.now().slice(0,10);}
 function months(){const offers=sim.content==='empty'?[]:base.games.map(g=>M.monthlyOffer(g.id,sim.giftExpiry)).filter(Boolean);return shell('我的礼包',`<div class="page-pad"><div class="gift-page-heading"><span class="tiny">${S.period.replace('-','年')}月</span><h2>会员专属游戏礼包</h2><p>Lv.${level()} ${LEVELS[level()].name}</p></div>${offers.length?offers.map(c=>`<article class="info-card member-gift-card" role="button" tabindex="0" data-action="view-member-code" data-g="${c.gameId}"><h3>${game(c.gameId).name}</h3><p class="member-gift-tier">Lv.${c.level} ${LEVELS[c.level].name} · ${c.title}</p><div class="member-gift-contents">${c.reward.split('、').map(item=>`<span>${esc(item)}</span>`).join('')}</div><p class="tiny">有效期至 ${c.expiry}</p>${btn('view-member-code','查看兑换码',{g:c.gameId},'primary full')}</article>`).join(''):empty(level()<2?'Lv.2起可查看会员礼包':'本月暂无配置的会员礼包')+(validOldCodes().length?btn('valid-member-code','查看仍有效的兑换码',{},'outline full'):'')}</div>`,{cls:'soft-bg'});}
 function service(){return shell('联系客服',`<div class="page-pad" style="text-align:center;padding-top:38px"><span class="row-icon" style="margin:0 auto 15px">${icon('chat')}</span><h2 style="font-size:21px">友趣游戏客服</h2><p class="summary">很高兴为你提供帮助</p>${btn('preview-single',image('assets/qr-service.svg','qr'),{src:'assets/qr-service.svg'})}<p style="font-size:14px;margin:10px 0">长按识别二维码，添加企业微信客服</p><p class="muted">也可点击二维码放大后识别<br>添加后，请向客服说明你遇到的问题</p></div>`);}
 const teamStatus={pending:'审核中',rejected:'未通过',published:'已发布',removed:'已下架'};
 function teamCard(t,own=false){return `<article class="team-card" data-action="team-detail" data-id="${t.id}"><div class="row-between"><span class="tag">${game(t.gameId).name}</span>${own?`<span class="audit ${t.status}">${teamStatus[t.status]}</span>`:''}</div><h3>${esc(t.title)}</h3><p>${esc(t.description).slice(0,70)}</p><div class="tiny">二维码有效期：${esc(t.expiry)}<br>${t.created}</div>${own&&t.reason?`<p class="status-line">${esc(t.reason)}</p>`:''}${own&&t.status!=='pending'?`<div class="team-actions">${t.status==='published'?btn('edit-team','编辑',{id:t.id},'outline')+btn('update-qr','更新二维码',{id:t.id},'outline'):['rejected','removed'].includes(t.status)?btn('edit-team','重新编辑',{id:t.id},'outline'):''}</div>`:''}</article>`;}
 function teams(){const list=sim.content==='empty'?[]:M.publicTeams().filter(t=>!ui.filter||t.gameId===ui.filter);return shell('找队友',gameChips()+refresh()+(list.length?list.slice(0,ui.limit).map(t=>teamCard(t)).join('')+end(list):empty('暂无组队帖')),{cls:'soft-bg',bottom:`<div class="bottom-bar">${btn('nav','发布组队',{page:'N20',g:ui.filter},'primary full')}</div>`})+btn('top',icon('arrow'),{},'top-button');}
 function teamDetail(){const t=team(),own=t?.owner===S.user.id&&isLogged();if(!t||sim.content==='empty'||t.status!=='published'&&!own)return shell('组队详情',empty(t?.status==='removed'?'内容已下架':'内容暂不可查看'));const person=M.playerProfile(t.owner);return shell('组队详情',`<article class="page-pad team-detail"><span class="tag">${game(t.gameId).name}</span>${own&&t.status!=='published'?`<div class="notice">${teamStatus[t.status]} · 仅自己可见${t.reason?'<br>'+esc(t.reason):''}</div>`:''}<h2>${esc(t.title)}</h2>${person?btn('player-profile',`<span class="avatar-wrap ${person.level>=4?'dynamic':''}" style="${frame(person.level)}">${image(person.avatar,'avatar')}</span><span><small>发起人</small><b>${esc(person.name)}</b></span>`,{id:t.owner},'team-initiator'):''}<div class="tiny">${t.created}</div><p class="team-desc">${esc(t.description)}</p><div class="info-card soft-bg" style="text-align:center"><h3>组队二维码</h3>${btn('preview-team-qr',image(t.qr,'qr'),{id:t.id})}<p class="muted">二维码有效期：${esc(t.expiry)}</p><p class="summary">点击放大，长按识别二维码自行联系</p></div>${!own?btn('start-chat',icon('chat',18)+' 聊一聊',{peer:t.owner},'primary full team-chat'):''}${!own?btn('report','举报',{id:t.id},'tiny'):''}</article>`);}
 function teamEditor(){const d=ui.teamDraft,t=d.editId?S.teams.find(t=>t.id===d.editId):null;if(d.editId&&!M.editableTeam(t))return shell('编辑组队',`<div class="page-pad"><div class="notice">${t?.status==='pending'?'审核中，暂不可编辑或删除':'当前内容不可编辑'}</div>${btn('nav','返回我的组队',{page:'N21'},'secondary full')}</div>`);return shell(d.editId?'编辑组队':'发布组队',`<form class="page-pad" id="team-form"><label class="field"><span>组队标题 *</span><input maxlength="30" data-bind="team.title" value="${esc(d.title)}" placeholder="写一个清晰的组队标题"><div class="char-count"><span id="team-title-count">${d.title.length}</span> / 30</div></label><label class="field"><span>所属游戏 *</span><select data-bind="team.gameId"><option value="0">请选择游戏</option>${base.games.map(g=>`<option value="${g.id}" ${Number(d.gameId)===g.id?'selected':''}>${g.name}</option>`).join('')}</select></label><label class="field"><span>组队描述 *</span><textarea maxlength="500" data-bind="team.description" placeholder="介绍你的组队需求或群聊内容">${esc(d.description)}</textarea><div class="char-count"><span id="team-desc-count">${d.description.length}</span> / 500</div></label><div class="field" id="qr-field"><span>组队二维码 *</span><div class="upload-wrap" style="width:110px">${d.qr?btn('preview-single',image(d.qr),{src:d.qr},'upload'):btn('upload-qr','＋<small>上传二维码</small>',{},'upload')}${d.qr?btn('remove-qr','×',{},'upload-remove'):''}</div>${d.qr?btn('upload-qr','更换二维码',{},'outline'):''}</div><label class="field"><span>二维码有效期 *</span><input type="date" data-bind="team.expiry" value="${esc(d.expiry)}" ${d.long?'disabled':''}><label class="check-row"><input type="checkbox" data-bind="team.long" ${d.long?'checked':''}>长期有效</label></label><p class="member-rules">提交后进行内容安全检测及人工审核，审核通过后公开展示。请勿发布无关推广或违规内容。</p>${t?btn('delete-team','删除组队',{id:t.id},'delete-team danger'):''}</form>`,{bottom:`<div class="bottom-bar">${btn('submit-team','提交审核',{},'primary full')}</div>`});}
 function myTeams(){const list=sim.content==='empty'?[]:S.teams.filter(t=>t.owner===S.user.id).sort((a,b)=>b.created.localeCompare(a.created));return shell('我的组队',list.length?list.slice(0,ui.limit).map(t=>teamCard(t,true)).join('')+end(list):empty('暂无组队帖','返回主页面，通过底部“发布”创建组队帖。'),{cls:'soft-bg'});}
