 function showGallery(mode){const items=mode==='avatar'?[1,2,3,4].map(i=>'assets/avatar-'+i+'.svg'):mode==='qr'?['assets/qr-group.svg','assets/qr-service.svg']:base.games.flatMap(g=>[g.cover,g.icon]);const o={title:mode==='qr'?'选择二维码':mode==='avatar'?'选择头像':'选择图片',sheet:true,mode,items,selected:[],html:'',buttons:[['本机图片',()=>uploadFile(mode)],['使用所选图片',()=>{if(!o.selected.length){toast('请选择图片');return;}applyImages(mode,o.selected.map(i=>items[i]));}]]};o.html=`<div class="upload-grid">${items.map((src,i)=>btn('gallery-select',image(src),{index:i},'upload')).join('')}</div>`;openLayer(o);}
 function applyImages(mode,images){if(!images.length){toast('图片读取失败，请重新选择');return;}if(mode==='post'){ui.postDraft.images=[...ui.postDraft.images,...images].slice(0,9);ui.dirty=true;}if(mode==='qr'){ui.teamDraft.qr=images[0];ui.dirty=true;}if(mode==='chat'){if(layers.at(-1)?.mode==='chat')layers.pop();confirmChatImage(images[0]);return;}if(mode==='avatar'){const profile=layers.find(o=>o.profile);if(profile){profile.draft.avatar=images[0];profile.html=profileHTML(profile.draft);}else S.user.avatar=images[0];}save();render();}
