 const p=post(o.pid);if(!p){closeLayer();toast('原帖已删除，无法回复');return;}const list=commentsFor(p),notice=o.notice?base.notifications.find(n=>String(n.id)===String(o.cid)):null,targetId=notice?.commentId||o.cid,par=list.find(c=>c.id===targetId||c.id===o.parent||c.replies?.some(r=>r.id===targetId));if(!par){o.sending=false;renderLayers();toast('原评论已删除，无法回复');return;}const r={id:M.id('c'),author:S.user.name,authorId:S.user.id,avatar:S.user.avatar,date:'刚刚',content:o.text.trim(),likeCount:0,liked:false,isAuthor:!!p.mine,replies:[]};
