 'create-order':()=>{if(sim.terminal==='restricted'){toast('当前环境暂不支持此商品支付');return;}if(!isLogged()){openLogin();return;}if(sim.submit==='fail'){toast('订单创建失败，请重试');return;}try{let o=ui.orderId?M.findOrder(ui.orderId):null;const reusable=o&&!o.credited&&o.gameId===Number(route.params.g)&&o.account===accountFor(route.params.g)&&o.face===ui.denom&&['unpaid','failed'].includes(o.status);if(!reusable)o=M.createOrder(route.params.g,ui.denom,accountFor(route.params.g));ui.orderId=o.id;save();if(reusable&&o.rate!==LEVELS[level()].rate)continueOrder(o.id);else{go('N07',{orderId:o.id});openPay(o);}}catch(e){toast(e.message);}},
