 const tabCache={};
 function tabSwitch(page){if(['N22','P01','P02','P03'].includes(route.id))tabCache[route.id]={ui:structuredClone(ui),scroll:$('.scroll')?.scrollTop||0};go(page,{}, {root:true});if(tabCache[page]){ui=structuredClone(tabCache[page].ui);render();$('.scroll').scrollTop=tabCache[page].scroll;}}
