 function resetDemo(){try{localStorage.removeItem(key);}catch{}M=createDemoModel(makeDemoData());S=M.state;route={id:'X_A',params:{g:1}};stack=[];layers=[];activeJump=null;sourceGame=1;externalReward=null;gameClaims.clear();Object.keys(tabCache).forEach(k=>delete tabCache[k]);ui.limit=10;ui.denom=0;ui.orderId='';ui.memberPreview=2;ui.chatDrafts={};ui.chatLimit=20;ui.comment='';ui.search='';ui.searched=false;ui.accountTab='discuss';ui.postDraft={content:'',images:[],remoteImages:[],tag:'',editId:'',keyboard:false,sending:false};ui.teamDraft={title:'',gameId:0,description:'',qr:'',expiry:'',long:false,editId:''};ui.dirty=false;sim={content:'normal',pay:'success',delivery:'arrived',reward:'success',identity:'ready',campaign:'1',submit:'success',activity:'live',terminal:'ready',giftExpiry:'month',recommend:'all',chatPeer:'reader-1',upload:'success'};routeSerial++;window.history.replaceState(null,'','#X_A');save();render();}
 actions['review-page']=d=>{if(d.page==='X_A'){go('X_A',{g:1},{root:true});return;}if(d.page==='X_B'){go('X_B',{g:2,mode:'guest'});return;}const defaults={P05:{id:'3001'},N24:{g:1},P08:{g:1},P09:{g:1},P10:{id:'1-1'},N02:{g:2},N04:{g:2},N07:{orderId:S.orders[0]?.id},N09:{orderId:S.orders[0]?.id},N19:{id:M.publicTeams()[0]?.id},N20:{g:1},N26:{userId:S.user.id},N27:{peerId:'reader-1'}};go(d.page,defaults[d.page]||{});};
 actions['review-login']=()=>{S.user.logged=!S.user.logged;layers=[];save();if(!S.user.logged&&(privatePages.has(route.id)||route.id==='P10'&&route.params.source==='member'))go('P03',{}, {root:true});else render();};
 actions['review-grade']=d=>{S.user.logged=true;M.memberFixture(Number(d.level));ui.memberPreview=level();save();render();toast('已切换等级样例');};
