 actions['review-team']=d=>{const t=route.id==='N19'?team():route.id==='N20'?S.teams.find(t=>t.id===ui.teamDraft.editId):S.teams.find(t=>t.owner===S.user.id&&t.status==='pending')||S.teams.find(t=>t.owner===S.user.id&&t.status==='published');if(!t){toast('暂无可切换记录');return;}t.status=d.status;t.reason=d.status==='rejected'?'请修改描述中的无关推广后重新提交。':d.status==='removed'?'经人工核查，内容涉及违规引流。':'';layers=[];save();render();toast('已接收审核结果');};
 actions['review-post']=d=>{const p=route.id==='P05'?post(route.params.id):S.posts.find(p=>p.mine&&p.status==='pending')||S.posts.find(p=>p.mine);if(!p?.mine){toast('请先打开本人帖子');return;}p.status=d.status;p.rejectReason=d.status==='rejected'?'图片或正文包含无关推广，请调整后重新提交。':'';save();render();};
 actions['review-reward']=()=>{if(route.id!=='X_B'||!activeJump){toast('本次跳转没有有效奖励资格');return;}settleReward('success');};
