 actions['review-chat-receive']=d=>{if(!isLogged()){toast('请先登录查看玩家会话');return;}const peer=route.id==='N27'?route.params.peerId:sim.chatPeer;try{M.receiveMessage(peer,d.type,d.type==='image'?game(2).cover:'你好！一起交流游戏日常吧。',route.id==='N27'&&route.params.peerId===peer);save();render();if(route.id==='N27')scrollChatBottom();toast('已收到示例消息');}catch(e){toast(e.message);}};
 function option(value,label,current){return`<option value="${value}" ${String(current)===String(value)?'selected':''}>${label}</option>`;}
