 if(['N18','N19','N20','N21'].includes(route.id))contextual='仅审核中／未通过／已发布／已下架；审核中不可编辑删除，已下架可重编重审。二维码到期继续展示，无需求标签或实时异常状态。';
 $('#logic-content').innerHTML=`<span class="logic-tag">${def.id} · ${isLogged()?'已登录':'游客'}</span><h3>页面用途</h3><p>${esc(def.purpose)}</p><h3>操作与规则</h3><p>${esc(def.rules)}</p><div class="logic-state">${esc(contextual||'点击页面内控件，流程导航和当前说明会同步更新。')}${layer?'<br>当前：'+esc(layer.title||'图片预览'):''}</div><h3>本页关键场景</h3><p>正常进入、返回及必要校验；下方可切换本地示例结果。</p>${specs[def.id]?`<details class="spec-details"><summary>展开完整确认方案</summary><div class="spec-text">${esc(specs[def.id])}</div></details>`:''}`;
 let controls=`<div class="scenario-row">${btn('review-login',isLogged()?'切换游客':'切换已登录')}</div>`;
 if(!route.id.startsWith('X_'))controls+=simSelect('content','展示状态',[['normal','正常'],...(['N22','P01','N23','P04','N24','P05','N25','P02','P07','P08','P09','N03','N08','N11','N18','N19','N21'].includes(route.id)?[['empty','空数据']]:[]),['loading','加载中'],['error','加载失败'],...(route.id==='N22'?[['jump-fail','去玩跳转失败'],['jump-missing','游戏跳转配置缺失']]:[])]);
 if(['N22','X_A','X_B','N04'].includes(route.id))controls+=simSelect('identity','目标账号对应关系',[['ready','已核实'],['missing','尚无游戏账号'],['error','读取失败']]);
 if(['X_A','N22','X_B'].includes(route.id)){controls+=simSelect('campaign','自动奖励活动（同游戏可换新活动）',[['1','第1期 · 相遇礼'],['2','第2期 · 新活动'],['none','暂无奖励活动']])+simSelect('reward','目标游戏发奖结果',[['success','成功'],['fail','失败'],['delay','结果延迟']]);if(route.id==='X_B')controls+=`<div class="scenario-row">${btn('review-reward','接收／重复回传成功结果')}</div>`;}
 if(['N04','N07','N08','N09'].includes(route.id))controls+=simSelect('pay','微信支付结果',[['success','支付成功'],['cancel','用户取消'],['fail','支付失败']])+simSelect('delivery','游戏到账结果',[['arrived','已到账'],['pending','到账中'],['error','到账异常']])+`<div class="scenario-row">${btn('review-refund','接收退款成功结果')}</div>`;
 if(['N10','N11','P03','N26','N04','N03'].includes(route.id))controls+=`<label>会员等级样例（替换本地充值样例）</label><div class="scenario-row">${[1,2,3,4,5].map(l=>btn('review-grade','Lv'+l,{level:l})).join('')}</div>`;
 if(route.id==='N03')controls+=`<label>月份</label><select data-review="month">${['2026-11','2026-12'].map(m=>option(m,m,S.period)).join('')}</select>`;
