 if(route.id==='P04')controls+=simSelect('recommend','无结果时的后台推荐配置（示例）',[['all','默认全部游戏'],['one','仅心动花城'],['none','未配置推荐内容']]);
 if(['P02','N27'].includes(route.id)){if(route.id==='P02')controls+=simSelect('chatPeer','接收消息的示例玩家',[['reader-1','小岛玩家'],['reader-2','布丁同学']]);controls+=`<div class="scenario-row">${btn('review-chat-receive','模拟收到文字',{type:'text'})}${btn('review-chat-receive','模拟收到图片',{type:'image'})}</div>`+simSelect('upload','图片读取结果',[['success','成功'],['fail','失败并保留会话']]);}
 controls+=simSelect('submit' ,'提交／保存结果',[['success','成功'],['fail','失败并保留内容']]);$('#scenario-controls').innerHTML=controls;
