 function render(){const renderer=renderers[route.id];if(!renderer)return;let html=renderer();if(sim.content==='loading'&&!route.id.startsWith('X_'))html=shell(PAGES.find(p=>p.id===route.id).name,'<div class="skeleton"><i></i><i></i><i></i></div>');if(sim.content==='error'&&!route.id.startsWith('X_'))html=shell(PAGES.find(p=>p.id===route.id).name,`<div class="error-box">${icon('refresh',40)}<p>加载失败，请稍后重试</p>${btn('refresh','重新加载',{},'secondary')}</div>`);$('#phone').innerHTML=html;renderLayers();renderLogic();if(route.id==='N04')$('#phone').classList.add('recharge-page');else $('#phone').classList.remove('recharge-page');}
 let touchStart=0,scrollThrottled=false;
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();const fn=actions[el.dataset.action];if(fn){try{fn(el.dataset);}catch(err){toast(err.message||'操作暂未完成，请重试');console.error(err);}}}else if(e.target.classList.contains('overlay'))closeLayer();});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.body.classList.contains('show-flow')||document.body.classList.contains('show-logic')){document.body.classList.remove('show-flow','show-logic');return;}if(layers.length)closeLayer();else if(route.id==='P06'&&ui.postDraft.keyboard){ui.postDraft.keyboard=false;render();}}if(e.key==='Enter'&&!e.shiftKey&&e.target.dataset.bind==='chat-text'){e.preventDefault();sendChat();}if(e.key==='Enter'&&!e.shiftKey&&e.target.dataset.bind==='reply-text'){e.preventDefault();submitReply();}if((e.key==='Enter'||e.key===' ')&&e.target.getAttribute('role')==='button'){e.preventDefault();e.target.click();}});
 document.addEventListener('input',e=>{const el=e.target,b=el.dataset.bind;if(!b)return;if(b==='search')ui.search=el.value;if(b==='comment')ui.comment=el.value;if(b==='chat-text'){ui.chatDrafts[route.params.peerId]=el.value;const send=$('[data-action=chat-send]');if(send)send.disabled=!el.value.trim()||!!M.threadFor(route.params.peerId)?.messages.some(m=>m.status==='sending');}
  if(b.startsWith('post.')){ui.postDraft[b.split('.')[1]]=el.value;ui.dirty=true;if($('#post-count'))$('#post-count').textContent=ui.postDraft.content.length;const submit=$('[data-action=submit-post]');if(submit)submit.disabled=!ui.postDraft.content.trim()&&!ui.postDraft.images.length;}
  if(b.startsWith('team.')){const k=b.split('.')[1];ui.teamDraft[k]=k==='long'?el.checked:el.value;ui.dirty=true;if(k==='long')$('[data-bind="team.expiry"]').disabled=el.checked;if($('#team-title-count'))$('#team-title-count').textContent=ui.teamDraft.title.length;if($('#team-desc-count'))$('#team-desc-count').textContent=ui.teamDraft.description.length;}
  const o=layers.at(-1);if(b==='old-code'&&o)o.selected=el.value;if(b==='reply-text'&&o?.reply){o.text=el.value;const send=$('.reply-send');if(send)send.disabled=!o.text.trim()||o.sending;}if(b==='report-text')o.text=el.value;if(b==='report-reason')o.reason=el.value;if(b==='profile-name')o.draft.name=el.value;if(b==='channel-search'){o.query=el.value;$('#channel-options').innerHTML=channelOptions(o);}
 });
 document.addEventListener('focusin',e=>{if(e.target.dataset.bind==='post.content'&&!ui.postDraft.keyboard)updateEditorKeyboard();});
 document.addEventListener('focusout',e=>{const o=layers.at(-1);if(e.target.dataset.bind==='reply-text'&&o?.reply&&!o.sending)setTimeout(()=>{if(layers.at(-1)===o&&!o.sending&&!document.activeElement?.matches('[data-action=reply-send]'))closeLayer();},150);});
 document.addEventListener('change',e=>{const el=e.target;if(el.dataset.sim){sim[el.dataset.sim]=el.value;if(el.dataset.sim==='delivery'&&['N07','N09'].includes(route.id)){const o=order();if(o?.credited&&['arrived','pending','error'].includes(o.status))o.status=el.value;}save();render();}if(el.dataset.review==='month'){S.period=el.value;save();render();}});
 document.addEventListener('submit',e=>{const form=e.target.dataset.form;if(!form)return;e.preventDefault();if(form==='search')doSearch();if(form==='code-search'){ui.searched=true;ui.limit=10;render();}if(form==='comment'){const p=post(route.params.id);if(!ui.comment.trim())return;if(sim.submit==='fail'){toast('评论失败，请重试');return;}const list=commentsFor(p);list.unshift({id:M.id('c'),author:isLogged()?S.user.name:'游客玩家',authorId:isLogged()?S.user.id:'guest',avatar:S.user.avatar,content:ui.comment.trim(),date:M.now(),likeCount:0,liked:false,replies:[]});p.commentCount++;ui.comment='';save();render();$('#comment-anchor')?.scrollIntoView({block:'start',behavior:'smooth'});toast('评论成功');}});
 document.addEventListener('scroll',e=>{const el=e.target;if(!el.classList?.contains('scroll'))return;const top=$('.top-button');if(top)top.style.display=el.scrollTop>el.clientHeight?'block':'none';if(!scrollThrottled&&el.scrollTop>0&&el.scrollHeight-el.scrollTop-el.clientHeight<25&&el.querySelector('[data-action=more]')){scrollThrottled=true;setTimeout(()=>{actions.more();scrollThrottled=false;},120);}},true);
 $('#phone').addEventListener('touchstart',e=>{touchStart=$('.scroll')?.scrollTop===0?e.touches[0].clientY:0;},{passive:true});$('#phone').addEventListener('touchend',e=>{if(touchStart&&e.changedTouches[0].clientY-touchStart>70)actions.refresh();touchStart=0;},{passive:true});
 $('#file-input').addEventListener('change',async e=>{if(!pendingFile)return;const mode=pendingFile.mode,files=[...e.target.files].filter(f=>f.type.startsWith('image/')).slice(0,mode==='post'?9-ui.postDraft.images.length:1);const images=await Promise.all(files.map(f=>new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve(null);r.readAsDataURL(f);})));applyImages(mode,images.filter(Boolean));pendingFile=null;});
